import six
from collections import OrderedDict
from lxml import etree


class ScfcFixerException(Exception):
    """Base exception for the SCFC fixer"""


class Xml(object):

    def __init__(self, path_or_xml):
        self.xml = etree.parse(path_or_xml).getroot() if isinstance(path_or_xml, six.string_types) else path_or_xml

    def save(self, path):
        """Saves this XML tree to a file at given path"""
        self._replace_self_closing_tags(self.xml)
        self.xml.getroottree().write(path, xml_declaration=True, encoding='UTF-8')

    def _replace_self_closing_tags(self, node):
        """BTS software doesn't support self closing tags in XML files e.g. <log/>. Method changes </tag> to <tag></tag> format."""
        if node.text is None:
            node.text = ""
        for child in node:
            self._replace_self_closing_tags(child)

    def _find_node(self, path, **path_args):
        parametrized_path = self._parametrize_path(path, **path_args)
        return self.xml.find(parametrized_path)

    def _find_node_or_raise(self, path, exception_class=ScfcFixerException, **path_args):
        node = self._find_node(path, **path_args)
        if node is None:
            self._raise_on_node_not_found(exception_class, self.xml, path, **path_args)
        else:
            return node

    def _raise_on_node_not_found(self, exception_class, starting_node, path, **path_args):
        additional_info_dict = OrderedDict()
        additional_info_dict['source'] = self.xml.base
        additional_info_dict['starting node'] = etree.tostring(starting_node, encoding='unicode').split('\n')[0]
        additional_info_dict['path'] = self._parametrize_path(path, **path_args)
        additional_info_dict.update(**path_args)
        additional_info = '\n'.join('{}: {}'.format(name, value) for name, value in additional_info_dict.items())
        raise exception_class("Could not find required node in the XML. Additional info:\n" + additional_info)

    def _find_all_nodes(self, path, **path_args):
        parametrized_path = self._parametrize_path(path, **path_args)
        return self.xml.findall(parametrized_path)

    def _parametrize_path(self, path, **path_args):
        path_args['*'] = '{*}'  # format treats {*} (any namespace) as one of the tokens
        return path.format(**path_args)

    def _add_element(self, parent_element, tag):
        element = etree.SubElement(parent_element, tag)
        self._fix_surrounding_indentation_after_adding(element)
        return element

    def _remove_element(self, element_to_remove):
        self._fix_indentation_before_removing(element_to_remove)
        parent_element = element_to_remove.getparent()
        parent_element.remove(element_to_remove)

    def _is_empty(self, element):
        return len(element) == 0

    def _fix_indentation_before_removing(self, element):
        predecessor = element.getprevious()
        parent = element.getparent()
        if predecessor is None:
            parent.text = element.tail
        else:
            predecessor.tail = element.tail

    def _fix_surrounding_indentation_after_adding(self, element):
        previous_sibling = element.getprevious()
        if previous_sibling is None:
            parent_element = element.getparent()
            element.tail = parent_element.text
            parent_element.text += ' '
        else:
            element.tail = previous_sibling.tail
            previous_sibling.tail += ' '

    def _fix_inner_indentation(self, element):
        previous_sibling = element.getprevious()
        if previous_sibling is None:
            parent_element = element.getparent()
            element.text = parent_element.text
        else:
            element.text = previous_sibling.tail

    @staticmethod
    def _get_managed_object_class(dist_name):
        parts = dist_name.split('/')
        last_part = parts[-1]
        return last_part.split('-')[0]

    def _print(self):
        """Use for debugging only"""
        print(etree.tostring(self.xml))

    def __eq__(self, other):
        return hasattr(other, 'xml') and self.xml == other.xml

    def __ne__(self, other):
        return not self == other
